"""Support dashboards generated by askdash (NexDash) from synthetic tickets, offline."""

import io
import json
import logging
import sys
from contextlib import redirect_stderr, redirect_stdout

import pytest

pytest.importorskip("nexdash")

from nexdash.executor import get_executor  # noqa: E402

from support_engine.cli import main  # noqa: E402
from support_engine.metrics import build_support_metrics  # noqa: E402
from support_engine.metrics.askdash import (  # noqa: E402
    INSIGHTS_MODEL,
    build_engine,
    conversation_rows,
    load_into_nexdash,
    report_models,
    serve_mcp_stdio,
)
from support_engine.metrics.demo import PII, check_dashboard, run_demo  # noqa: E402
from support_engine.metrics.synthetic import synthetic_outcomes, synthetic_tickets  # noqa: E402

PERIOD = {"start": "2026-04-01", "end": "2026-06-30"}


@pytest.fixture(scope="module")
def metrics():
    tickets = synthetic_tickets()
    return build_support_metrics(tickets, synthetic_outcomes(tickets))


@pytest.fixture()
def engine(metrics):
    executor = get_executor("sqlite:///:memory:")
    load_into_nexdash(executor, metrics)
    yield build_engine(executor)
    executor.close()


def kpis(report):
    return {pid: p["value"] for pid, p in report["data"]["panels"].items() if p["kind"] == "kpi"}


def test_support_metrics_dashboard_from_synthetic_tickets(engine, metrics) -> None:
    report = engine.run({"model": "support_metrics", "parameters": PERIOD})
    assert report["errors"] == {}
    values = kpis(report)
    assert values["volume"] == len(metrics.tickets)
    rows = conversation_rows(metrics)
    deflected = sum(r["deflected_flag"] for r in rows) / len(rows)
    assert values["deflection_rate"] == pytest.approx(deflected)
    sentiment = {r["sentiment"]: r["ticket_count"] for r in report["data"]["panels"]["sentiment"]["rows"]}
    assert sentiment["negative"] == metrics.report.sentiment.negative
    assert sum(sentiment.values()) == len(metrics.tickets)
    assert check_dashboard(report["dashboard"]["html"]) == []


def test_support_insights_dashboard_carries_the_analytics(engine, metrics) -> None:
    report = engine.run({"model": "support_insights", "parameters": PERIOD, "locale": "pt-BR"})
    assert report["errors"] == {}
    values = kpis(report)
    assert values["high_risk"] == len(metrics.report.high_risk())
    alerting = {i for a in metrics.report.alerts for i in a.ticket_ids}
    assert values["trend_alert_tickets"] == len(alerting) > 0
    assert values["hours_saved"] == pytest.approx(metrics.report.roi.hours_saved, abs=1e-2)
    panels = report["data"]["panels"]
    assert panels["root_causes"]["rows"] and all(r["root_cause"] != "none" for r in panels["root_causes"]["rows"])
    assert "version:2.3" in {r["root_cause"] for r in panels["root_causes"]["rows"]}
    assert [r["risk_level"] for r in panels["risk_levels"]["rows"]][0] == "high"
    assert {r["queue"] for r in panels["sentiment_by_queue"]["rows"]} == {"billing", "access", "reports"}
    html = report["dashboard"]["html"]
    assert check_dashboard(html) == [] and "Support insights" in html
    assert not any(value in json.dumps(report) for value in PII)


def test_period_and_team_filters(engine, metrics) -> None:
    full = kpis(engine.run({"model": "support_insights", "parameters": PERIOD}))
    tier1 = kpis(engine.run({"model": "support_insights", "parameters": {**PERIOD, "team": "tier1"}}))
    tier2 = kpis(engine.run({"model": "support_insights", "parameters": {**PERIOD, "team": "tier2"}}))
    assert tier1["high_risk"] + tier2["high_risk"] == full["high_risk"]
    assert tier1["trend_alert_tickets"] == 0 and tier2["trend_alert_tickets"] == full["trend_alert_tickets"]
    june = engine.run({"model": "support_metrics", "parameters": {"start": "2026-06-01", "end": "2026-06-30"}})
    in_june = sum(1 for t in metrics.tickets if t.created_at.strftime("%Y-%m") == "2026-06")
    assert kpis(june)["volume"] == in_june
    assert june["data"]["panels"]["volume"]["previous_value"] is not None


def test_models_are_listed_and_refuse_bad_requests(engine) -> None:
    from nexdash.service import ServiceError

    names = [m["name"] for m in engine.list_models()]
    assert {"support_metrics", "support_insights"} <= set(names) and set(report_models()) == set(names)
    described = engine.describe_model("support_insights")
    assert {p["id"] for p in described["panels"]} == {p.id for p in INSIGHTS_MODEL.panels}
    for bad in (
        {"model": "support_insights", "sql": "select 1"},
        {"model": "support_insights", "parameters": {"end": "2026-01-01", "start": "2026-02-01"}},
        {"model": "no_such_model"},
    ):
        with pytest.raises(ServiceError):
            engine.run(bad)


def test_reloading_replaces_the_tables(metrics) -> None:
    executor = get_executor("sqlite:///:memory:")
    try:
        load_into_nexdash(executor, metrics)
        counts = load_into_nexdash(executor, metrics)
        assert counts == {"support_metrics": len(metrics.tickets), "support_insights": len(metrics.tickets)}
        report = build_engine(executor).run({"model": "support_metrics", "output": "data"})
        assert kpis(report)["volume"] == len(metrics.tickets) and "dashboard" not in report
    finally:
        executor.close()


def test_round_trip_over_rest_and_mcp(tmp_path, caplog, monkeypatch) -> None:
    import support_engine.metrics.demo as demo

    token = "known-token-for-the-log-check-0123456789"
    monkeypatch.setattr(demo.secrets, "token_urlsafe", lambda _n: token)
    with caplog.at_level(logging.DEBUG):
        summary = run_demo(tmp_path)
    assert summary["problems"] == []
    assert set(summary["transports"]) == {"rest", "mcp"}
    assert summary["transports"]["rest"]["support_insights"]["high_risk"] > 0
    assert sorted(p.name for p in tmp_path.iterdir()) == ["support_insights.html", "support_metrics.html"]
    assert not any(value in caplog.text for value in PII)
    assert token not in caplog.text


def test_cli_loads_tables_and_writes_dashboards(tmp_path) -> None:
    tickets = synthetic_tickets(60)
    source = tmp_path / "tickets.json"
    source.write_text(json.dumps([json.loads(t.model_dump_json()) for t in tickets]), encoding="utf-8")
    results = tmp_path / "results.jsonl"
    results.write_text("\n".join(json.dumps(r) for r in synthetic_outcomes(tickets)), encoding="utf-8")
    db = tmp_path / "nexdash.db"
    out = tmp_path / "dash"
    buf = io.StringIO()
    with redirect_stdout(buf):
        code = main(
            [
                "metrics",
                "--input",
                str(source),
                "--agent-results",
                str(results),
                "--nexdash-db",
                f"sqlite:///{db.as_posix()}",
                "--dashboard-out",
                str(out),
                "--team",
                "tier1",
                "--locale",
                "pt-BR",
            ]
        )
    assert code == 0, buf.getvalue()
    assert "into support_insights" in buf.getvalue()
    for name in ("support_metrics", "support_insights"):
        assert check_dashboard((out / f"{name}.html").read_text(encoding="utf-8")) == []
    executor = get_executor(f"sqlite:///{db.as_posix()}")
    try:
        assert kpis(build_engine(executor).run({"model": "support_metrics"}))["volume"] == len(tickets)
    finally:
        executor.close()

    err = io.StringIO()
    with redirect_stderr(err):
        assert main(["metrics", "--input", str(tmp_path / "missing.json")]) == 1
        assert main(["metrics", "--input", str(source), "--start", "2026-06-01", "--end", "2026-05-01"]) == 2


def test_mcp_over_stdio_serves_support_insights(metrics, monkeypatch) -> None:
    messages = [
        {"jsonrpc": "2.0", "id": 1, "method": "initialize", "params": {"protocolVersion": "2025-06-18"}},
        {"jsonrpc": "2.0", "method": "notifications/initialized"},
        {
            "jsonrpc": "2.0",
            "id": 2,
            "method": "tools/call",
            "params": {"name": "nexdash_run_report", "arguments": {"model": "support_insights", "output": "data"}},
        },
    ]
    stdout = io.StringIO()
    monkeypatch.setattr(sys, "stdin", io.StringIO("\n".join(json.dumps(m) for m in messages) + "\n"))
    monkeypatch.setattr(sys, "stdout", stdout)
    serve_mcp_stdio("sqlite:///:memory:", metrics=metrics)
    replies = [json.loads(line) for line in stdout.getvalue().splitlines() if line.strip()]
    result = next(r for r in replies if r.get("id") == 2)["result"]
    assert result["isError"] is False
    assert result["structuredContent"]["data"]["panels"]["high_risk"]["value"] == len(metrics.report.high_risk())
